    // Mode values control the operation of [New] and [NewFromFiles].
    // New computes the package documentation for the given package AST.
    // New takes ownership of the AST pkg and may edit or overwrite it.
    // To have the [Examples] fields populated, use [NewFromFiles] and include
    // the package's _test.go files.
    Package* New(ast::Package* pkg, gocpp::string importPath, Mode mode)
    {
        reader r = {};
        rec::readPackage(gocpp::recv(r), pkg, mode);
        rec::computeMethodSets(gocpp::recv(r));
        rec::cleanupTypes(gocpp::recv(r));
        auto p = gocpp::InitPtr<Package>([=](auto& x) {
            x.Doc = r.doc;
            x.Name = pkg->Name;
            x.ImportPath = importPath;
            x.Imports = sortedKeys(r.imports);
            x.Filenames = r.filenames;
            x.Notes = r.notes;
            x.Bugs = noteBodies(r.notes["BUG"_s]);
            x.Consts = sortedValues(r.values, token::CONST);
            x.Types = sortedTypes(r.types, mode & AllMethods != 0);
            x.Vars = sortedValues(r.values, token::VAR);
            x.Funcs = sortedFuncs(r.funcs, true);
            x.importByName = r.importByName;
            x.syms = gocpp::make(gocpp::Tag<gocpp::map<gocpp::string, bool>>());
        });

        rec::collectValues(gocpp::recv(p), p->Consts);
        rec::collectValues(gocpp::recv(p), p->Vars);
        rec::collectTypes(gocpp::recv(p), p->Types);
        rec::collectFuncs(gocpp::recv(p), p->Funcs);

        return p;
    }

    void rec::collectValues(Package* p, gocpp::slice<Value*> values)
    {
        for(auto [gocpp_ignored, v] : values)
        {
            for(auto [gocpp_ignored, name] : v->Names)
            {
                p->syms[name] = true;
            }
        }
    }

    void rec::collectTypes(Package* p, gocpp::slice<Type*> types)
    {
        for(auto [gocpp_ignored, t] : types)
        {
            if(p->syms[t->Name])
            {
                // Shouldn't be any cycles but stop just in case.
                continue;
            }
            p->syms[t->Name] = true;
            rec::collectValues(gocpp::recv(p), t->Consts);
            rec::collectValues(gocpp::recv(p), t->Vars);
            rec::collectFuncs(gocpp::recv(p), t->Funcs);
            rec::collectFuncs(gocpp::recv(p), t->Methods);
        }
    }

    void rec::collectFuncs(Package* p, gocpp::slice<Func*> funcs)
    {
        for(auto [gocpp_ignored, f] : funcs)
        {
            if(f->Recv != ""_s)
            {
                auto r = strings::TrimPrefix(f->Recv, "*"_s);
                if(auto i = strings::IndexByte(r, '['); i >= 0)
                {
                    // remove type parameters
                    r = r.make_slice(0, i);
                }
                p->syms[r + "."_s + f->Name] = true;
            }
            else
            {
                p->syms[f->Name] = true;
            }
        }
    }

    // NewFromFiles computes documentation for a package.
    //
    // The package is specified by a list of *ast.Files and corresponding
    // file set, which must not be nil.
    // NewFromFiles uses all provided files when computing documentation,
    // so it is the caller's responsibility to provide only the files that
    // match the desired build context. "go/build".Context.MatchFile can
    // be used for determining whether a file matches a build context with
    // the desired GOOS and GOARCH values, and other build constraints.
    // The import path of the package is specified by importPath.
    //
    // Examples found in _test.go files are associated with the corresponding
    // type, function, method, or the package, based on their name.
    // If the example has a suffix in its name, it is set in the
    // [Example.Suffix] field. [Examples] with malformed names are skipped.
    //
    // Optionally, a single extra argument of type [Mode] can be provided to
    // control low-level aspects of the documentation extraction behavior.
    //
    // NewFromFiles takes ownership of the AST files and may edit them,
    // unless the PreserveAST Mode bit is on.
    std::tuple<Package*, gocpp::error> NewFromFiles(token::FileSet* fset, gocpp::slice<ast::File*> files, gocpp::string importPath, gocpp::slice<go_any> opts)
    {
        // Check for invalid API usage.
        if(fset == nullptr)
        {
            gocpp::panic(mocklib::Errorf("doc.NewFromFiles: no token.FileSet provided (fset == nil)"_s));
        }
        Mode mode = {};
        //Go switch emulation
        {
            auto condition = len(opts);
            int conditionId = -1;
            if(condition == 0) { conditionId = 0; }
            else if(condition == 1) { conditionId = 1; }
            switch(conditionId)
            {
                // There can only be 0 or 1 options, so a simple switch works for now.
                case 0:
                    break;
                // Nothing to do.
                case 1:
                {
                    auto [m, ok] = gocpp::getValue<Mode>(opts[0]);
                    if(! ok)
                    {
                        gocpp::panic(mocklib::Errorf("doc.NewFromFiles: option argument type must be doc.Mode"_s));
                    }
                    mode = m;
                    break;
                }
                default:
                    gocpp::panic(mocklib::Errorf("doc.NewFromFiles: there must not be more than 1 option argument"_s));
                    break;
            }
        }

        // Collect .go and _test.go files.
        auto goFiles = gocpp::make(gocpp::Tag<gocpp::map<gocpp::string, ast::File*>>());
        gocpp::slice<ast::File*> testGoFiles = gocpp::make(gocpp::Tag<gocpp::map<gocpp::string, ast::File*>>());
        for(auto [i, gocpp_ignored] : files)
        {
            auto f = rec::File(gocpp::recv(fset), rec::Pos(gocpp::recv(files[i])));
            if(f == nullptr)
            {
                return {nullptr, mocklib::Errorf("file files[%d] is not found in the provided file set"_s, i)};
            }
            //Go switch emulation
            {
                auto name = rec::Name(gocpp::recv(f));
                int conditionId = -1;
                if(strings::HasSuffix(name, ".go"_s) && ! strings::HasSuffix(name, "_test.go"_s)) { conditionId = 0; }
                else if(strings::HasSuffix(name, "_test.go"_s)) { conditionId = 1; }
                switch(conditionId)
                {
                    case 0:
                        goFiles[name] = files[i];
                        break;
                    case 1:
                        testGoFiles = append(testGoFiles, files[i]);
                        break;
                    default:
                        return {nullptr, mocklib::Errorf("file files[%d] filename %q does not have a .go extension"_s, i, name)};
                        break;
                }
            }
        }

        // TODO(dmitshur,gri): A relatively high level call to ast.NewPackage with a simpleImporter
        // ast.Importer implementation is made below. It might be possible to short-circuit and simplify.
        // Compute package documentation.
        // Ignore errors that can happen due to unresolved identifiers.
        auto [pkg, gocpp_id_0] = ast::NewPackage(fset, goFiles, simpleImporter, nullptr);
        auto p = New(pkg, importPath, mode);
        classifyExamples(p, Examples(testGoFiles));
        return {p, nullptr};
    }

    // simpleImporter returns a (dummy) package object named by the last path
    // component of the provided package path (as is the convention for packages).
    // This is sufficient to resolve package identifiers without doing an actual
    // import. It never returns an error.
    std::tuple<ast::Object*, gocpp::error> simpleImporter(gocpp::map<gocpp::string, ast::Object*> imports, gocpp::string path)
    {
        auto pkg = imports[path];
        if(pkg == nullptr)
        {
            // note that strings.LastIndex returns -1 if there is no "/"
            pkg = ast::NewObj(ast::Pkg, path.make_slice(strings::LastIndex(path, "/"_s) + 1));
            // required by ast.NewPackage for dot-import
            pkg->Data = ast::NewScope(nullptr);
            imports[path] = pkg;
        }
        return {pkg, nullptr};
    }

    // lookupSym reports whether the package has a given symbol or method.
    //
    // If recv == "", HasSym reports whether the package has a top-level
    // const, func, type, or var named name.
    //
    // If recv != "", HasSym reports whether the package has a type
    // named recv with a method named name.
    bool rec::lookupSym(Package* p, gocpp::string recv, gocpp::string name)
    {
        if(recv != ""_s)
        {
            return p->syms[recv + "."_s + name];
        }
        return p->syms[name];
    }

    // lookupPackage returns the import path identified by name
    // in the given package. If name uniquely identifies a single import,
    // then lookupPackage returns that import.
    // If multiple packages are imported as name, importPath returns "", false.
    // Otherwise, if name is the name of p itself, importPath returns "", true,
    // to signal a reference to p.
    // Otherwise, importPath returns "", false.
    std::tuple<gocpp::string, bool> rec::lookupPackage(Package* p, gocpp::string name)
    {
        gocpp::string importPath;
        bool ok;
        if(auto [path, ok] = p->importByName[name]; ok)
        {
            if(path == ""_s)
            {
                // multiple imports used the name
                return {""_s, false};
            }
            // found import
            return {path, true};
        }
        if(p->Name == name)
        {
            // allow reference to this package
            return {""_s, true};
        }
        // unknown name
        return {""_s, false};
    }

    // Parser returns a doc comment parser configured
    // for parsing doc comments from package p.
    // Each call returns a new parser, so that the caller may
    // customize it before use.
    comment::Parser* rec::Parser(Package* p)
    {
        return gocpp::InitPtr<comment::Parser>([=](auto& x) {
            x.LookupPackage = [&](auto x){ return rec::lookupPackage(p, x); };
            x.LookupSym = [&](auto x, auto y){ return rec::lookupSym(p, x, y); };
        });
    }

    // Printer returns a doc comment printer configured
    // for printing doc comments from package p.
    // Each call returns a new printer, so that the caller may
    // customize it before use.
    comment::Printer* rec::Printer(Package* p)
    {
        // No customization today, but having p.Printer()
        // gives us flexibility in the future, and it is convenient for callers.
        return new comment::Printer {};
    }

    // HTML returns formatted HTML for the doc comment text.
    //
    // To customize details of the HTML, use [Package.Printer]
    // to obtain a [comment.Printer], and configure it
    // before calling its HTML method.
    gocpp::slice<unsigned char> rec::HTML(Package* p, gocpp::string text)
    {
        return rec::HTML(gocpp::recv(rec::Printer(gocpp::recv(p))), rec::Parse(gocpp::recv(rec::Parser(gocpp::recv(p))), text));
    }

